"""Standalone carbin/database/string-table tool. Drop files onto Mod Diff.cmd.
Generated from the maintained exporters and mod_diff_launcher.py.in.
No external Python packages are required. First input = vanilla, second = edited.
CLI: mod_diff.py carbin <export|import|diff|apply> ...
     mod_diff.py database <vanilla> <edited> [database exporter options]
     mod_diff.py strings <export|diff|languages> ...
Drop one STR/language ZIP to export it, or two to extract changed/new strings.
"""
import sys
from pathlib import Path
import json
import zipfile
from contextlib import closing



CARBIN_SOURCE = '"""Lossless FH2 carbin conversion and record-based mod patches (Python 3.10+).\n\nexport CARBIN JSON | import JSON CARBIN | diff VANILLA MODDED PATCH | apply BASE PATCH OUT\nInputs may also be ZIP paths: export car.zip JSON extracts the sole non-debug carbin.\nOnly the FH2 CarScene v5 / render model v15 layout is accepted deliberately.\n"""\nimport argparse\nimport copy\nimport hashlib\nimport json\nfrom pathlib import Path\nimport struct\nimport sys\nimport zipfile\n\nMAX_BYTES = 32 * 1024 * 1024\nMAX_COUNT = 4096\nFORMAT = \'fh2-carbin\'\nPATCH = \'fh2-carbin-patch\'\n\n\ndef fields(d, required, optional=\'\'):\n    if not isinstance(d, dict):\n        raise ValueError(\'Expected JSON object\')\n    keys = set(required.split(\',\')) if required else set()\n    extra = set(optional.split(\',\')) if optional else set()\n    if keys - d.keys() or d.keys() - keys - extra - {\'_comment\'}:\n        raise ValueError(f\'Missing or unknown fields: {sorted(keys - d.keys() | (d.keys() - keys - extra - {"_comment"}))}\')\n\n\nclass Reader:\n    def __init__(self, data):\n        if len(data) > MAX_BYTES:\n            raise ValueError(\'Carbin exceeds 32 MiB\')\n        self.data, self.pos = data, 0\n\n    def raw(self, size):\n        if size < 0 or size > len(self.data) - self.pos:\n            raise ValueError(f\'Truncated carbin at 0x{self.pos:x}\')\n        result = self.data[self.pos:self.pos + size]\n        self.pos += size\n        return result\n\n    def number(self, size=4, signed=False):\n        return int.from_bytes(self.raw(size), \'little\', signed=signed)\n\n    def string(self):\n        return self.raw(self.number()).decode(\'utf-8\', errors=\'strict\')\n\n    def array(self, read):\n        count = self.number()\n        if count > MAX_COUNT:\n            raise ValueError(f\'Excessive record count {count}\')\n        return [read(self) for _ in range(count)]\n\n\nclass Writer:\n    def __init__(self):\n        self.data = bytearray()\n\n    def raw(self, value):\n        self.data.extend(value)\n        if len(self.data) > MAX_BYTES:\n            raise ValueError(\'Carbin exceeds 32 MiB\')\n\n    def number(self, value, size=4, signed=False):\n        if type(value) is not int:\n            raise ValueError(\'Integer required\')\n        self.raw(value.to_bytes(size, \'little\', signed=signed))\n\n    def string(self, value):\n        if \'\\0\' in value:\n            raise ValueError(\'Embedded NUL in carbin string\')\n        data = value.encode(\'utf-8\')\n        self.number(len(data))\n        self.raw(data)\n\n    def hex(self, value, size=None):\n        data = bytes.fromhex(value)\n        if len(value) != len(data) * 2:\n            raise ValueError(\'Hexadecimal data must not contain whitespace\')\n        if size is not None and len(data) != size:\n            raise ValueError(f\'Expected {size} bytes of hexadecimal data\')\n        self.raw(data)\n\n    def array(self, values, write):\n        if not isinstance(values, list) or len(values) > MAX_COUNT:\n            raise ValueError(\'Invalid record array\')\n        self.number(len(values))\n        for value in values:\n            write(self, value)\n\n\ndef read_model(r):\n    v = r.number(2)\n    if v != 15:\n        raise ValueError(f\'Unsupported render model version {v}; expected FH2 v15\')\n    d = dict(version=v, path=r.string(), transform_hex=r.raw(64).hex(),\n             lod=r.number(2), bone_name=r.string(), bone_index=r.number(2),\n             flags=r.number(1), draw_groups=r.number(signed=True))\n    d[\'material_overrides\'] = r.array(lambda r: dict(name=r.string(), data_hex=r.raw(r.number()).hex()))\n    d[\'material_indices\'] = r.array(lambda r: dict(name=r.string(), value=r.number()))\n    d[\'has_hash\'] = r.number(1)\n    d[\'hash_hex\'] = r.raw(8 if d[\'has_hash\'] else 0).hex()\n    d[\'unknown8_hex\'] = r.raw(4).hex()\n    def ao(r):\n        version = r.number(2)\n        if version not in (1, 2, 3):\n            raise ValueError(f\'Unsupported AO map version {version}\')\n        return dict(version=version, path=r.string(),\n                    data_hex=r.raw(8 + (16 if version >= 2 else 3) + 1 + (2 if version >= 3 else 0)).hex())\n    d[\'ao_maps\'] = r.array(ao)\n    d.update(unknown10_hex=r.raw(1).hex(), unknown11_hex=r.raw(18).hex(),\n             part_name=r.string(), guid=r.raw(16).hex(), unknown14_hex=r.raw(20).hex(),\n             unknown15_hex=r.raw(4).hex())\n    return d\n\n\ndef write_model(w, d):\n    fields(d, \'version,path,transform_hex,lod,bone_name,bone_index,flags,draw_groups,material_overrides,material_indices,has_hash,hash_hex,unknown8_hex,ao_maps,unknown10_hex,unknown11_hex,part_name,guid,unknown14_hex,unknown15_hex\', \'upgrade_ids\')\n    if d[\'version\'] != 15:\n        raise ValueError(\'Only FH2 render model v15 is supported\')\n    w.number(15, 2)\n    w.string(d[\'path\'])\n    w.hex(d[\'transform_hex\'], 64)\n    w.number(d[\'lod\'], 2)\n    w.string(d[\'bone_name\'])\n    w.number(d[\'bone_index\'], 2)\n    w.number(d[\'flags\'], 1)\n    w.number(d[\'draw_groups\'], signed=True)\n    def material(w, d):\n        fields(d, \'name,data_hex\')\n        w.string(d[\'name\'])\n        data = bytes.fromhex(d[\'data_hex\'])\n        w.number(len(data))\n        w.raw(data)\n    w.array(d[\'material_overrides\'], material)\n    def index(w, d):\n        fields(d, \'name,value\')\n        w.string(d[\'name\'])\n        w.number(d[\'value\'])\n    w.array(d[\'material_indices\'], index)\n    if d[\'has_hash\'] not in (0, 1):\n        raise ValueError(\'has_hash must be 0 or 1\')\n    w.number(d[\'has_hash\'], 1)\n    w.hex(d[\'hash_hex\'], 8 if d[\'has_hash\'] else 0)\n    w.hex(d[\'unknown8_hex\'], 4)\n    def ao(w, d):\n        fields(d, \'version,path,data_hex\')\n        v = d[\'version\']\n        if v not in (1, 2, 3):\n            raise ValueError(\'Unsupported AO version\')\n        w.number(v, 2)\n        w.string(d[\'path\'])\n        w.hex(d[\'data_hex\'], 8 + (16 if v >= 2 else 3) + 1 + (2 if v >= 3 else 0))\n    w.array(d[\'ao_maps\'], ao)\n    w.hex(d[\'unknown10_hex\'], 1)\n    w.hex(d[\'unknown11_hex\'], 18)\n    w.string(d[\'part_name\'])\n    w.hex(d[\'guid\'], 16)\n    w.hex(d[\'unknown14_hex\'], 20)\n    w.hex(d[\'unknown15_hex\'], 4)\n\n\ndef read_upgrade(r):\n    v = r.number(2)\n    if v not in (1, 2, 3):\n        raise ValueError(f\'Unsupported upgrade version {v}\')\n    return dict(version=v, level=r.number(1), is_stock=r.number(1), id=r.number(signed=True),\n                car_body_id=r.number(signed=True), parent_is_stock=r.number(1),\n                data_hex=r.raw(32 if v >= 2 else 0).hex())\n\n\ndef write_upgrade(w, d):\n    fields(d, \'version,level,is_stock,id,car_body_id,parent_is_stock,data_hex\')\n    v = d[\'version\']\n    if v not in (1, 2, 3):\n        raise ValueError(\'Unsupported upgrade version\')\n    w.number(v, 2)\n    w.number(d[\'level\'], 1)\n    w.number(d[\'is_stock\'], 1)\n    w.number(d[\'id\'], signed=True)\n    w.number(d[\'car_body_id\'], signed=True)\n    w.number(d[\'parent_is_stock\'], 1)\n    w.hex(d[\'data_hex\'], 32 if v >= 2 else 0)\n\n\ndef read_shared(r):\n    ids = r.array(lambda r: r.number())\n    d = read_model(r)\n    d[\'upgrade_ids\'] = ids\n    return d\n\n\ndef write_shared(w, d):\n    w.array(d[\'upgrade_ids\'], lambda w, n: w.number(n))\n    write_model(w, d)\n\n\ndef read_part(r):\n    dispatch, v = r.number(1), r.number(2)\n    if v not in (1, 2):\n        raise ValueError(f\'Unsupported part version {v}\')\n    return dict(dispatch=dispatch, version=v, part_type=r.number(), models=r.array(read_model),\n                data_hex=r.raw(32 if v >= 2 else 0).hex())\n\n\ndef write_part(w, d):\n    fields(d, \'dispatch,version,part_type,models,data_hex\')\n    v = d[\'version\']\n    if v not in (1, 2):\n        raise ValueError(\'Unsupported part version\')\n    w.number(d[\'dispatch\'], 1)\n    w.number(v, 2)\n    w.number(d[\'part_type\'])\n    w.array(d[\'models\'], write_model)\n    w.hex(d[\'data_hex\'], 32 if v >= 2 else 0)\n\n\ndef read_group(r):\n    v = r.number(2)\n    if v != 3:\n        raise ValueError(f\'Unsupported upgrade group version {v}\')\n    return dict(version=v, part_type=r.number(), upgrades=r.array(read_upgrade), models=r.array(read_shared))\n\n\ndef write_group(w, d):\n    fields(d, \'version,part_type,upgrades,models\')\n    if d[\'version\'] != 3:\n        raise ValueError(\'Only FH2 upgrade group v3 is supported\')\n    w.number(3, 2)\n    w.number(d[\'part_type\'])\n    w.array(d[\'upgrades\'], write_upgrade)\n    w.array(d[\'models\'], write_shared)\n\n\ndef decode(data):\n    r = Reader(data)\n    v = r.number(2)\n    if v != 5:\n        raise ValueError(f\'Unsupported CarScene version {v}; expected FH2 v5\')\n    d = dict(format=FORMAT, format_version=1, version=v, guid=r.raw(16).hex(), flags=r.number(1),\n             ordinal=r.number(), media_name=r.string(), skeleton=r.string(), unknown=r.number(2),\n             parts=r.array(read_part), groups=r.array(read_group))\n    if r.pos != len(data):\n        raise ValueError(f\'Unrecognized trailing bytes at 0x{r.pos:x}\')\n    for kind in (\'parts\', \'groups\'):\n        indexed(d[kind], kind)\n        for group in d[kind]:\n            indexed(group[\'models\'], \'models\')\n            if kind == \'groups\':\n                indexed(group[\'upgrades\'], \'upgrades\')\n    return d\n\n\ndef encode(d):\n    fields(d, \'format,format_version,version,guid,flags,ordinal,media_name,skeleton,unknown,parts,groups\')\n    if d[\'format\'] != FORMAT or d[\'format_version\'] != 1 or d[\'version\'] != 5:\n        raise ValueError(\'Unsupported carbin JSON format/version\')\n    w = Writer()\n    w.number(5, 2)\n    w.hex(d[\'guid\'], 16)\n    w.number(d[\'flags\'], 1)\n    w.number(d[\'ordinal\'])\n    w.string(d[\'media_name\'])\n    w.string(d[\'skeleton\'])\n    w.number(d[\'unknown\'], 2)\n    w.array(d[\'parts\'], write_part)\n    w.array(d[\'groups\'], write_group)\n    return bytes(w.data)\n\n\ndef identity(d, kind):\n    if kind == \'models\':\n        return bytes.fromhex(d[\'guid\']).hex()\n    return d[\'id\'] if kind == \'upgrades\' else d[\'part_type\']\n\n\ndef indexed(items, kind):\n    result = {identity(d, kind): d for d in items}\n    if len(result) != len(items):\n        raise ValueError(f\'Ambiguous duplicate identity in {kind}\')\n    return result\n\n\ndef changes(before, after, kind):\n    a, b = indexed(before, kind), indexed(after, kind)\n    ops = []\n    for key in sorted(a.keys() - b.keys(), key=str):\n        ops.append(dict(op=\'remove\', key=key))\n    for item in after:\n        key = identity(item, kind)\n        if a.get(key) != item:\n            if kind in (\'parts\', \'groups\') and key in a:\n                old = a[key]\n                metadata = {k: v for k, v in item.items() if k not in (\'models\', \'upgrades\')}\n                if metadata != {k: v for k, v in old.items() if k not in (\'models\', \'upgrades\')}:\n                    raise ValueError(\'Changing existing group/part metadata is unsupported; use full replacement\')\n                op = dict(op=\'merge\', key=key, models=changes(old[\'models\'], item[\'models\'], \'models\'))\n                if kind == \'groups\':\n                    op[\'upgrades\'] = changes(old[\'upgrades\'], item[\'upgrades\'], \'upgrades\')\n                ops.append(op)\n            else:\n                ops.append(dict(op=\'upsert\', key=key, value=item))\n    # Retained records preserve base order; inserted records append. Order has no\n    # selection semantics (part IDs/GUIDs do).\n    return ops\n\n\ndef diff(base, modified):\n    a, b = decode(base), decode(modified)\n    if {k: v for k, v in a.items() if k not in (\'parts\', \'groups\')} != {k: v for k, v in b.items() if k not in (\'parts\', \'groups\')}:\n        raise ValueError(\'Car identity/header changed; compare matching versions of the same car\')\n    d = dict(format=PATCH, format_version=1, base_sha256=hashlib.sha256(base).hexdigest(),\n             ordinal=a[\'ordinal\'], media_name=a[\'media_name\'],\n             parts=changes(a[\'parts\'], b[\'parts\'], \'parts\'), groups=changes(a[\'groups\'], b[\'groups\'], \'groups\'))\n    return d\n\n\ndef upgrade_warnings(base, modified):\n    """Report newly introduced dangling model links without inventing physics/IDs.\n\n    A render model\'s upgrade_ids and the group\'s upgrades are independent arrays.\n    The diff remains lossless: guessing a template would silently change the edit.\n    Existing vanilla dangling IDs are not reported again.\n    """\n    def missing(document):\n        result = {}\n        for group in document[\'groups\']:\n            known = {u[\'id\'] & 0xffffffff for u in group[\'upgrades\']}\n            for model in group[\'models\']:\n                for ident in set(model[\'upgrade_ids\']) - known:\n                    result.setdefault((group[\'part_type\'], ident), []).append(model[\'path\'])\n        return result\n    old, new = missing(decode(base)), missing(decode(modified))\n    messages = []\n    for (part, ident), paths in sorted(new.items()):\n        if (part, ident) not in old:\n            messages.append(\n                f\'Group part_type={part}: model upgrade_ids references ID {ident}, \'\n                f\'but this group has no matching upgrades record. Models: {", ".join(paths)}. \'\n                \'In ForzaTech Studio, add/duplicate an entry in the part group’s Upgrades \'\n                \'list and set its ID to the same value. Match its level, stock flags and \'\n                \'car_body_id to your database upgrade row. Adding a model or an Upgrade ID \'\n                \'to that model alone does not create this record; the diff cannot infer it.\')\n    return messages\n\n\ndef merge_list(items, ops, kind):\n    indexed(items, kind)\n    seen = set()\n    for op in ops:\n        key = op[\'key\']\n        if kind == \'models\':\n            key = bytes.fromhex(key).hex()\n        if key in seen:\n            raise ValueError(\'Duplicate patch operation key\')\n        seen.add(key)\n        positions = {identity(d, kind): i for i, d in enumerate(items)}\n        i = positions.get(key)\n        if op[\'op\'] == \'remove\':\n            fields(op, \'op,key\')\n            if i is not None:\n                items.pop(i)\n        elif op[\'op\'] == \'upsert\':\n            fields(op, \'op,key,value\')\n            value = copy.deepcopy(op[\'value\'])\n            if identity(value, kind) != key:\n                raise ValueError(\'Operation key does not match record identity\')\n            if i is None:\n                items.append(value)\n            else:\n                items[i] = value\n        elif op[\'op\'] == \'merge\' and kind in (\'parts\', \'groups\') and i is not None:\n            fields(op, \'op,key\', \'models,upgrades\' if kind == \'groups\' else \'models\')\n            merge_list(items[i][\'models\'], op.get(\'models\', []), \'models\')\n            if kind == \'groups\':\n                merge_list(items[i][\'upgrades\'], op.get(\'upgrades\', []), \'upgrades\')\n        else:\n            raise ValueError(\'Invalid operation or missing merge target\')\n\n\ndef apply(base, patch):\n    fields(patch, \'format,format_version,ordinal,media_name\', \'base_sha256,parts,groups,description\')\n    d = decode(base)\n    if patch[\'format\'] != PATCH or type(patch[\'format_version\']) is not int or patch[\'format_version\'] != 1:\n        raise ValueError(\'Unsupported patch format/version\')\n    if patch[\'ordinal\'] != d[\'ordinal\'] or patch[\'media_name\'].lower() != d[\'media_name\'].lower():\n        raise ValueError(\'Patch targets another car\')\n    for kind in (\'parts\', \'groups\'):\n        merge_list(d[kind], patch.get(kind, []), kind)\n    result = encode(d)\n    decode(result)\n    return result\n\n\ndef read_car(path):\n    if path.suffix.lower() == \'.zip\':\n        with zipfile.ZipFile(path) as z:\n            names = [n for n in z.namelist() if n.lower().endswith(\'.carbin\')]\n            if len(names) != 1:\n                raise ValueError(\'ZIP must contain exactly one .carbin\')\n            if z.getinfo(names[0]).file_size > MAX_BYTES:\n                raise ValueError(\'Oversized carbin ZIP member\')\n            return z.read(names[0])\n    if path.stat().st_size > MAX_BYTES:\n        raise ValueError(\'Carbin exceeds 32 MiB\')\n    return path.read_bytes()\n\n\ndef load_json(path):\n    def pairs(values):\n        d = {}\n        for key, value in values:\n            if key in d:\n                raise ValueError(f\'Duplicate JSON key {key}\')\n            d[key] = value\n        return d\n    return json.loads(path.read_text(encoding=\'utf-8-sig\'), object_pairs_hook=pairs)\n\n\ndef main():\n    p = argparse.ArgumentParser(description=__doc__)\n    p.add_argument(\'command\', choices=(\'export\', \'import\', \'diff\', \'apply\'))\n    p.add_argument(\'paths\', nargs=\'+\', type=Path)\n    args = p.parse_args()\n    if len(args.paths) != (3 if args.command in (\'diff\', \'apply\') else 2):\n        p.error(\'export/import require INPUT OUTPUT; diff/apply require BASE MODIFIED_OR_PATCH OUTPUT\')\n    try:\n        paths = args.paths\n        if paths[-1].resolve() in [q.resolve() for q in paths[:-1]]:\n            raise ValueError(\'Output must differ from inputs\')\n        if args.command == \'export\':\n            data = read_car(paths[0])\n            result = decode(data)\n            if encode(result) != data:\n                raise ValueError(\'Lossless round-trip verification failed\')\n        elif args.command == \'import\':\n            result = encode(load_json(paths[0]))\n            decode(result)\n        elif args.command == \'diff\':\n            base, modified = map(read_car, paths[:2])\n            result = diff(base, modified)\n            for warning in upgrade_warnings(base, modified):\n                print(f\'Warning: {warning}\', file=sys.stderr)\n            # Record reordering alone does not change behavior. Validate all fields.\n            applied = decode(apply(base, result))\n            target = decode(modified)\n            def canonical(d):\n                if isinstance(d, list):\n                    return sorted((canonical(x) for x in d), key=lambda x: json.dumps(x, sort_keys=True))\n                return {k: canonical(v) for k, v in d.items()} if isinstance(d, dict) else d\n            if canonical(applied) != canonical(target):\n                raise ValueError(\'Patch verification failed\')\n        else:\n            base, patch = read_car(paths[0]), load_json(paths[1])\n            if patch.get(\'base_sha256\') != hashlib.sha256(base).hexdigest():\n                print(\'Warning: base SHA-256 differs; applying record operations to the supplied base.\')\n            result = apply(base, patch)\n        if isinstance(result, bytes):\n            paths[-1].write_bytes(result)\n        else:\n            paths[-1].write_text(json.dumps(result, indent=2, ensure_ascii=False) + \'\\n\', encoding=\'utf-8\')\n        print(f\'Wrote {paths[-1]}\')\n    except (ValueError, KeyError, OSError, OverflowError, TypeError, zipfile.BadZipFile) as e:\n        p.exit(1, f\'Error: {e}\\n\')\n\n\nif __name__ == \'__main__\':\n    main()\n'
DATABASE_SOURCE = '#!/usr/bin/env python3\n"""Export SQLite data changes as an addon JSON, without editing either input."""\nfrom __future__ import annotations\n\nimport argparse\nfrom collections import Counter, defaultdict\nfrom contextlib import closing\nimport hashlib\nimport json\nimport math\nfrom pathlib import Path\nimport re\nimport sqlite3\nimport sys\n\n\nclass ExportError(Exception):\n    pass\n\n\ndef identifier(name):\n    return \'"\' + name.replace(\'"\', \'""\') + \'"\'\n\n\ndef encode(value):\n    if isinstance(value, bytes):\n        return {\'blob_hex\': value.hex()}\n    if isinstance(value, float) and not math.isfinite(value):\n        raise ExportError(\'Non-finite numbers cannot be represented in addon JSON.\')\n    return value\n\n\ndef decode(value):\n    if isinstance(value, dict) and set(value) == {\'blob_hex\'}:\n        return bytes.fromhex(value[\'blob_hex\'])\n    return value\n\n\ndef typed(value):\n    return type(value).__name__, value\n\n\ndef row_identity(row, columns):\n    return tuple(typed(row[column]) for column in columns)\n\n\ndef encoded_row(row):\n    return {name: encode(value) for name, value in row.items()}\n\n\ndef ordered(rows):\n    return sorted(rows, key=lambda row: json.dumps(encoded_row(row), ensure_ascii=True,\n                                                  separators=(\',\', \':\'), allow_nan=False))\n\n\ndef schema(connection):\n    return dict(((kind, name), (table, sql)) for kind, name, table, sql in connection.execute(\n        "SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE name NOT LIKE \'sqlite_%\'"))\n\n\ndef table_info(connection, table):\n    return list(connection.execute(f\'PRAGMA table_xinfo({identifier(table)})\'))\n\n\ndef columns_for(connection, table):\n    info = table_info(connection, table)\n    if any(row[6] for row in info):\n        raise ExportError(f\'{table}: generated/hidden columns are not supported.\')\n    return [row[1] for row in info]\n\n\ndef read_rows(connection, table, columns):\n    names = \',\'.join(map(identifier, columns))\n    return [dict(zip(columns, row)) for row in connection.execute(\n        f\'SELECT {names} FROM {identifier(table)}\')]\n\n\ndef choose_key(connection, table, columns, requested):\n    if table in requested:\n        key = requested[table]\n        if not key or len(set(key)) != len(key) or any(name not in columns for name in key):\n            raise ExportError(f\'{table}: invalid explicit key {key!r}. Column names are case-sensitive.\')\n        return key\n    info = table_info(connection, table)\n    primary = [row[1] for row in sorted(info, key=lambda row: row[5]) if row[5]]\n    if primary:\n        return primary\n    for index in connection.execute(f\'PRAGMA index_list({identifier(table)})\'):\n        if not index[2] or index[4]:  # Unique, non-partial indexes only.\n            continue\n        key = [row[2] for row in connection.execute(f\'PRAGMA index_info({identifier(index[1])})\')]\n        if key and all(name in columns for name in key):\n            return key\n    return []\n\n\ndef indexed_rows(rows, key, table):\n    result = {}\n    for row in rows:\n        values = row_identity(row, key)\n        if any(row[name] is None for name in key) or values in result:\n            raise ExportError(f\'{table}: key {key!r} contains NULL or duplicate values. \'\n                              \'Use --key TABLE=Column1,Column2 to specify a stable unique key.\')\n        result[values] = row\n    return result\n\n\ndef multiset(rows, columns):\n    return Counter(row_identity(row, columns) for row in rows)\n\n\ndef unkeyed_difference(before, after, columns):\n    old, new = multiset(before, columns), multiset(after, columns)\n    added, removed = new - old, old - new\n    result = []\n    for counts in (added, removed):\n        rows = []\n        for identity, count in counts.items():\n            rows.extend(dict(zip(columns, (value for _, value in identity))) for _ in range(count))\n        result.append(ordered(rows))\n    return result\n\n\ndef required_records(base, changes, written):\n    records = defaultdict(dict)\n\n    def require(table, row):\n        encoded = encoded_row(row)\n        records[table][json.dumps(encoded, sort_keys=True)] = encoded\n\n    for table, operations in changes.items():\n        for operation in operations.get(\'update\', []) + operations.get(\'delete\', []):\n            require(table, {key: decode(value) for key, value in operation[\'where\'].items()})\n        groups = defaultdict(list)\n        for row in base.execute(f\'PRAGMA foreign_key_list({identifier(table)})\'):\n            groups[row[0]].append(row)\n        for group in groups.values():\n            group.sort(key=lambda row: row[1])\n            parent = group[0][2]\n            parent_key = [row[1] for row in sorted(table_info(base, parent), key=lambda row: row[5])\n                          if row[5]]\n            destinations = [row[4] if row[4] is not None else\n                            parent_key[row[1]] if row[1] < len(parent_key) else None for row in group]\n            if any(name is None for name in destinations):\n                raise ExportError(f\'{table}: cannot resolve foreign key to {parent}.\')\n            for row in written.get(table, []):\n                values = [row[item[3]] for item in group]\n                if any(value is None for value in values):\n                    continue\n                where = \' AND \'.join(identifier(name) + \' IS ?\' for name in destinations)\n                if base.execute(f\'SELECT 1 FROM {identifier(parent)} WHERE {where} LIMIT 1\', values).fetchone():\n                    require(parent, dict(zip(destinations, values)))\n    return {table: list(records[table].values()) for table in sorted(records)}\n\n\ndef data_view_schema(base, custom, old_schema, new_schema):\n    """Treat a table\'s filtered replacement as a snapshot, never runtime SQL.\n\n    Accept only SELECT * FROM a new, otherwise identical backing table WHERE\n    predicate. All remaining schema changes still fail the normal comparison.\n    """\n    normalized = dict(new_schema)\n    snapshots = []\n    name = r\'(?:"(?:[^"]|"")+"|\\[[^\\]]+\\]|`[^`]+`|[A-Za-z_][A-Za-z_0-9]*)\'\n    pattern = re.compile(r\'^\\s*CREATE\\s+VIEW\\s+\' + name + r\'\\s+AS\\s+SELECT\\s+\\*\\s+FROM\\s+(\'\n                         + name + r\')\\s+WHERE\\s+.+?\\s*;?\\s*$\', re.I | re.S)\n    for (kind, table), definition in old_schema.items():\n        if kind != \'table\' or (\'table\', table) in new_schema or (\'view\', table) not in new_schema:\n            continue\n        match = pattern.fullmatch(new_schema[\'view\', table][1] or \'\')\n        if not match:\n            continue\n        backing = match[1]\n        if backing[0] in (\'"\', \'[\', \'`\'):\n            backing = backing[1:-1].replace(\'""\', \'"\')\n        backing_definition = new_schema.get((\'table\', backing))\n        if not backing_definition or any(key[1] == backing for key in old_schema):\n            continue\n        def body(sql):\n            return sql[sql.index(\'(\'):].strip().rstrip(\';\').strip() if sql and \'(\' in sql else None\n        if (body(definition[1]) != body(backing_definition[1]) or\n                table_info(base, table) != table_info(custom, backing) or\n                [(r[1], r[2], r[6]) for r in table_info(base, table)] !=\n                [(r[1], r[2], r[6]) for r in table_info(custom, table)]):\n            continue\n        if (\'table\', backing) not in normalized:\n            continue  # One backing table cannot satisfy multiple replacements.\n        del normalized[\'view\', table]\n        del normalized[\'table\', backing]\n        normalized[\'table\', table] = definition\n        snapshots.append({\'table\': table, \'backing_table\': backing,\n                          \'behavior\': \'export-time rows only; no runtime filter\'})\n    return normalized, snapshots\n\n\ndef compare(base, custom, addon_id=None, *, keys=None, updates=\'error\', deletes=\'error\',\n            conflicts=\'error\', foreign_keys=\'error\', tables=None, target=\'media/stripped/gamedbRC.slt\', base_hash=None):\n    if foreign_keys not in (\'error\', \'allow\'):\n        raise ExportError(\'Invalid foreign-key policy; expected error or allow.\')\n    keys = keys or {}\n    old_schema, new_schema = schema(base), schema(custom)\n    new_schema, snapshots = data_view_schema(base, custom, old_schema, new_schema)\n    if old_schema != new_schema:\n        different = sorted({name for kind, name in old_schema.keys() | new_schema.keys()\n                            if old_schema.get((kind, name)) != new_schema.get((kind, name))})\n        raise ExportError(\'Schema changes are not data overrides: \' + \', \'.join(different))\n    all_tables = sorted(name for kind, name in old_schema if kind == \'table\')\n    selected = set(tables) if tables else set(all_tables)\n    unknown = (selected | keys.keys()) - set(all_tables)\n    if unknown:\n        raise ExportError(\'Unknown table(s): \' + \', \'.join(sorted(unknown)))\n    changes, written, counts, skipped = {}, {}, {}, {}\n    for table in all_tables:\n        if table not in selected:\n            continue\n        columns = columns_for(base, table)\n        before, after = read_rows(base, table, columns), read_rows(custom, table, columns)\n        key = choose_key(base, table, columns, keys)\n        operations = {\'key\': key}\n        added, changed, removed = [], [], []\n        if key:\n            old, new = indexed_rows(before, key, table), indexed_rows(after, key, table)\n            added = [row for identity, row in new.items() if identity not in old]\n            removed = [row for identity, row in old.items() if identity not in new]\n            for identity in old.keys() & new.keys():\n                previous, current = old[identity], new[identity]\n                fields = [name for name in columns if typed(previous[name]) != typed(current[name])]\n                if fields:\n                    changed.append((previous, current, fields))\n        else:\n            added, removed = unkeyed_difference(before, after, columns)\n            if removed and deletes != \'ignore\':\n                raise ExportError(f\'{table}: {len(removed)} removed/replaced row(s), but no stable key. \'\n                                  \'Use --key TABLE=Column1,Column2. Row order/rowid is never used as identity.\')\n        if changed and updates == \'error\':\n            raise ExportError(f\'{table}: {len(changed)} existing row(s) changed. \'\n                              \'Use --updates override to export field overrides, or --updates ignore.\')\n        if removed and deletes == \'error\':\n            raise ExportError(f\'{table}: {len(removed)} row(s) removed. \'\n                              \'Use --deletes include to export explicit deletions, or --deletes ignore.\')\n        if added:\n            operations[\'insert\'] = [encoded_row(row) for row in ordered(added)]\n        if changed and updates == \'override\':\n            changed.sort(key=lambda item: json.dumps(encoded_row({name: item[0][name] for name in key})))\n            operations[\'update\'] = [\n                {\'where\': encoded_row({name: previous[name] for name in key}),\n                 \'set\': encoded_row({name: current[name] for name in fields}),\n                 \'expect\': encoded_row({name: previous[name] for name in fields})}\n                for previous, current, fields in changed]\n        if removed and deletes == \'include\':\n            operations[\'delete\'] = [\n                {\'where\': encoded_row({name: row[name] for name in key}), \'expect\': encoded_row(row)}\n                for row in ordered(removed)]\n        ignored = {\'update\': len(changed) if updates == \'ignore\' else 0,\n                   \'delete\': len(removed) if deletes == \'ignore\' else 0}\n        if any(ignored.values()):\n            skipped[table] = ignored\n        if len(operations) > 1:\n            changes[table] = operations\n            written[table] = added + ([row for _, row, _ in changed] if updates == \'override\' else [])\n            counts[table] = {name: len(operations.get(name, [])) for name in (\'insert\', \'update\', \'delete\')}\n    document = {\'format_version\': 2,\n                \'target\': {\'database\': target}, \'policy\': {\'id_conflicts\': \'error\', \'update_conflicts\': conflicts, \'foreign_keys\': foreign_keys},\n                \'requires\': {\'records\': required_records(base, changes, written)}, \'tables\': changes}\n    if addon_id:\n        document[\'addon_id\'] = addon_id\n    if base_hash:\n        document[\'target\'][\'base_sha256\'] = base_hash\n    report = {\'tables_scanned\': len(selected), \'tables_changed\': len(changes), \'tables\': counts,\n              \'totals\': {name: sum(row[name] for row in counts.values())\n                         for name in (\'insert\', \'update\', \'delete\')}, \'ignored_changes\': skipped}\n    if snapshots:\n        report[\'filtered_view_snapshots\'] = snapshots\n    return document, report\n\n\ndef replay(connection, document):\n    """Validate proposed merge semantics in a caller-owned scratch connection."""\n    for table, operations in document[\'tables\'].items():\n        for kind in (\'delete\', \'update\'):\n            for operation in operations.get(kind, []):\n                selector = {key: decode(value) for key, value in operation[\'where\'].items()}\n                if not selector or list(selector) != operations[\'key\']:\n                    raise ExportError(f\'{table}: operation must select its complete declared key.\')\n                where = \' AND \'.join(identifier(name) + \' IS ?\' for name in selector)\n                cursor = connection.execute(f\'SELECT * FROM {identifier(table)} WHERE {where}\',\n                                            list(selector.values()))\n                matches = cursor.fetchall()\n                if len(matches) != 1:\n                    raise ExportError(f\'{table}: override/delete selector must match exactly one row: {selector}\')\n                row = dict(zip((item[0] for item in cursor.description), matches[0]))\n                if document[\'policy\'][\'update_conflicts\'] == \'error\':\n                    for name, expected in operation[\'expect\'].items():\n                        if typed(row[name]) != typed(decode(expected)):\n                            raise ExportError(f\'{table}: conflicting change to {name} at {selector}\')\n                if kind == \'delete\':\n                    connection.execute(f\'DELETE FROM {identifier(table)} WHERE {where}\', list(selector.values()))\n                else:\n                    values = {key: decode(value) for key, value in operation[\'set\'].items()}\n                    assignments = \',\'.join(identifier(name) + \'=?\' for name in values)\n                    connection.execute(f\'UPDATE {identifier(table)} SET {assignments} WHERE {where}\',\n                                       list(values.values()) + list(selector.values()))\n        for row in operations.get(\'insert\', []):\n            key = operations[\'key\']\n            if key:\n                where = \' AND \'.join(identifier(name) + \' IS ?\' for name in key)\n                if connection.execute(f\'SELECT 1 FROM {identifier(table)} WHERE {where}\',\n                                      [decode(row[name]) for name in key]).fetchone():\n                    raise ExportError(f\'{table}: insert key already exists; inserts never replace rows.\')\n            columns = \',\'.join(map(identifier, row))\n            placeholders = \',\'.join(\'?\' for _ in row)\n            connection.execute(f\'INSERT INTO {identifier(table)} ({columns}) VALUES ({placeholders})\',\n                               [decode(value) for value in row.values()])\n\n\ndef describe_foreign_keys(connection, violations):\n    """Readable evidence; rowid is diagnostic only, never an exported selector."""\n    details = []\n    for table, rowid, parent, rule_id in violations:\n        group = sorted((r for r in connection.execute(f\'PRAGMA foreign_key_list({identifier(table)})\')\n                        if r[0] == rule_id), key=lambda r: r[1])\n        columns = columns_for(connection, table)\n        row = connection.execute(f\'SELECT * FROM {identifier(table)} WHERE rowid=?\', (rowid,)).fetchone() if rowid is not None else None\n        row = dict(zip(columns, row)) if row is not None else {}\n        key = choose_key(connection, table, columns, {})\n        parent_key = [r[1] for r in sorted(table_info(connection, parent), key=lambda r:r[5]) if r[5]]\n        detail = {\'table\': table, \'rowid\': rowid, \'key\': encoded_row({k:row[k] for k in key if k in row}),\n                  \'parent_table\': parent, \'foreign_key_id\': rule_id,\n                  \'references\': [{\'column\': r[3], \'value\': encode(row.get(r[3])),\n                                  \'parent_column\': r[4] or parent_key[r[1]]} for r in group]}\n        details.append(detail)\n    return details\n\n\ndef scratch_foreign_keys(base, document):\n    with closing(sqlite3.connect(\':memory:\')) as scratch:\n        base.backup(scratch)\n        baseline = Counter(scratch.execute(\'PRAGMA foreign_key_check\'))\n        replay(scratch, document)\n        added = Counter(scratch.execute(\'PRAGMA foreign_key_check\')) - baseline\n        return describe_foreign_keys(scratch, added.elements())\n\n\ndef validate(base, custom, document, report, selected=None):\n    with closing(sqlite3.connect(\':memory:\')) as merged:\n        base.backup(merged)\n        baseline = Counter(merged.execute(\'PRAGMA foreign_key_check\'))\n        with merged:\n            replay(merged, document)\n            if list(merged.execute(\'PRAGMA quick_check\')) != [(\'ok\',)]:\n                raise ExportError(\'Scratch merge failed SQLite integrity checks.\')\n            added = Counter(merged.execute(\'PRAGMA foreign_key_check\')) - baseline\n            foreign_key_policy = document.get(\'policy\', {}).get(\'foreign_keys\', \'error\')\n            if foreign_key_policy not in (\'error\', \'allow\'):\n                raise ExportError(\'Invalid foreign-key policy; expected error or allow.\')\n            violations = describe_foreign_keys(merged, added.elements())\n            if added and foreign_key_policy != \'allow\':\n                first = \'; \'.join(f"{v[\'table\']} key={v[\'key\']} -> {v[\'parent_table\']} {v[\'references\']}" for v in violations[:3])\n                raise ExportError(f\'Scratch merge introduces {sum(added.values())} declared foreign-key violations: {first}. \'\n                                  \'Use --foreign-keys allow to preserve these references as-is (requires Extra Options 0.2.210+).\')\n            compared = 0\n            for kind, table in schema(base):\n                if kind != \'table\' or table in report[\'ignored_changes\']:\n                    continue\n                expected = custom if not selected or table in selected else base\n                columns = columns_for(base, table)\n                if multiset(read_rows(merged, table, columns), columns) != multiset(read_rows(expected, table, columns), columns):\n                    raise ExportError(f\'{table}: scratch merge differs from the expected database.\')\n                compared += 1\n    report[\'validation\'] = {\'scratch_merge\': \'PASS\', \'tables_compared\': compared,\n                            \'sqlite_integrity\': \'ok\', \'no_new_declared_foreign_key_violations\': not bool(added),\n                            \'foreign_key_policy\': foreign_key_policy,\n                            \'new_declared_foreign_key_violations\': violations}\n\n\ndef sha256(path):\n    digest = hashlib.sha256()\n    with path.open(\'rb\') as stream:\n        for block in iter(lambda: stream.read(1024 * 1024), b\'\'):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef open_readonly(path):\n    if not path.is_file():\n        raise ExportError(f\'Database not found: {path}\')\n    wal = Path(str(path) + \'-wal\')\n    if wal.exists() and wal.stat().st_size:\n        raise ExportError(f\'{path.name}: active WAL sidecar found. Export a checkpointed, closed database first.\')\n    connection = sqlite3.connect(path.as_uri() + \'?mode=ro\', uri=True)\n    connection.execute(\'PRAGMA query_only=ON\')\n    connection.execute(\'PRAGMA trusted_schema=OFF\')\n    if list(connection.execute(\'PRAGMA quick_check\')) != [(\'ok\',)]:\n        connection.close()\n        raise ExportError(f\'Invalid SQLite database: {path}\')\n    connection.execute(\'BEGIN\')\n    return connection\n\n\ndef write_json(path, data, force):\n    with path.open(\'w\' if force else \'x\', encoding=\'utf-8\', newline=\'\\n\') as stream:\n        json.dump(data, stream, indent=2, ensure_ascii=False, allow_nan=False)\n        stream.write(\'\\n\')\n\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter,\n        epilog=\'Example: python export_database_diff.py vanilla.slt custom.slt -o database.json --updates override\\n\'\n               \'Supported by Extra Options. This script does not install mods or modify game files.\')\n    parser.add_argument(\'vanilla\', type=Path, help=\'Unmodified SQLite/SLT database\')\n    parser.add_argument(\'custom\', type=Path, help=\'Modified database; filtered table views are exported as row snapshots\')\n    parser.add_argument(\'-o\', \'--output\', type=Path, default=Path(\'database.json\'))\n    parser.add_argument(\'--addon-id\', help=\'Optional legacy metadata; mod.json or the containing folder identifies the mod\')\n    parser.add_argument(\'--id-conflicts\', choices=(\'error\', \'nearest\', \'last_wins\'), default=\'error\',\n                        help=\'Duplicate inserts: reject, assign nearest IDs, or share IDs with the later mod supplying the row\')\n    parser.add_argument(\'--foreign-keys\', choices=(\'error\', \'allow\'), default=\'error\',\n                        help=\'Reject new dangling declared references, or preserve them as-is (requires Extra Options 0.2.210+)\')\n    parser.add_argument(\'--target\', default=\'media/stripped/gamedbRC.slt\', help=\'Game-relative target database path\')\n    parser.add_argument(\'--updates\', choices=(\'error\', \'override\', \'ignore\'), default=\'error\')\n    parser.add_argument(\'--deletes\', choices=(\'error\', \'include\', \'ignore\'), default=\'error\')\n    parser.add_argument(\'--conflicts\', choices=(\'error\', \'last-wins\'), default=\'error\',\n                        help=\'Whether changed expected values reject an override or allow later addons to win\')\n    parser.add_argument(\'--key\', action=\'append\', default=[], metavar=\'TABLE=COL1,COL2\',\n                        help=\'Explicit unique key for a table; repeat for multiple tables\')\n    parser.add_argument(\'--table\', action=\'append\', help=\'Export only this table; repeat for multiple tables\')\n    parser.add_argument(\'--report\', type=Path, help=\'Optional comparison/validation report JSON\')\n    parser.add_argument(\'--force\', action=\'store_true\', help=\'Replace existing output/report files\')\n    args = parser.parse_args(argv)\n    try:\n        inputs = [args.vanilla.resolve(), args.custom.resolve()]\n        outputs = [path.resolve() for path in (args.output, args.report) if path is not None]\n        if len(set(outputs)) != len(outputs):\n            raise ExportError(\'Output and report must be different files.\')\n        for output in outputs:\n            if any(output == path or output.exists() and path.exists() and output.samefile(path) for path in inputs):\n                raise ExportError(\'Output/report must not overwrite either input database.\')\n            if output.exists() and not args.force:\n                raise ExportError(f\'Output already exists: {output}. Use --force to replace it.\')\n        keys = {}\n        for value in args.key:\n            table, separator, names = value.partition(\'=\')\n            if not separator or not table or not names or table in keys:\n                raise ExportError(f\'Invalid/duplicate --key: {value}\')\n            keys[table] = names.split(\',\')\n        addon_id = args.addon_id\n        if addon_id and not re.fullmatch(\'[a-z0-9]+(?:-[a-z0-9]+)*\', addon_id):\n            raise ExportError(\'Addon ID must use lowercase letters, digits and single hyphens.\')\n        target = args.target.replace(\'\\\\\', \'/\')\n        if target.startswith(\'/\') or \':\' in target or any(part in (\'\', \'.\', \'..\') for part in target.split(\'/\')):\n            raise ExportError(\'--target must be a relative game content path without traversal.\')\n        with closing(open_readonly(inputs[0])) as base, closing(open_readonly(inputs[1])) as custom:\n            hashes = [sha256(path) for path in inputs]\n            document, report = compare(base, custom, addon_id, keys=keys, updates=args.updates,\n                                       deletes=args.deletes, conflicts=args.conflicts.replace(\'-\', \'_\'),\n                                       tables=args.table, target=target, base_hash=hashes[0], foreign_keys=args.foreign_keys)\n            document[\'policy\'][\'id_conflicts\'] = args.id_conflicts\n            # Exercise exactly what will be written, including JSON/BLOB round trips.\n            document = json.loads(json.dumps(document, ensure_ascii=False, allow_nan=False))\n            validate(base, custom, document, report, set(args.table) if args.table else None)\n            if hashes != [sha256(path) for path in inputs]:\n                raise ExportError(\'An input changed during comparison. Close its editor/game and retry.\')\n        report.update({\'result\': \'PASS\', \'format_version\': 2,\n                       \'inputs\': {label: {\'file\': str(path), \'sha256\': digest}\n                                  for label, path, digest in zip((\'vanilla\', \'custom\'), inputs, hashes)},\n                       \'input_files_unchanged\': True, \'loader_implemented\': True})\n        write_json(outputs[0], document, args.force)\n        if args.report:\n            write_json(outputs[1], report, args.force)\n        totals = report[\'totals\']\n        print(f"Exported {totals[\'insert\']} inserts, {totals[\'update\']} overrides and "\n              f"{totals[\'delete\']} deletions across {report[\'tables_changed\']} tables to {outputs[0]}")\n        if report[\'ignored_changes\']:\n            print(\'Ignored changes: \' + json.dumps(report[\'ignored_changes\'], ensure_ascii=False))\n        if report.get(\'filtered_view_snapshots\'):\n            print(\'Filtered views exported as row snapshots; rows added by other mods are not filtered.\')\n        violations = report[\'validation\'][\'new_declared_foreign_key_violations\']\n        if violations:\n            print(f\'Preserved {len(violations)} declared foreign-key violations as requested by policy.foreign_keys=allow.\')\n        print(\'Scratch merge validated; both source databases are unchanged.\')\n        return 0\n    except (ExportError, sqlite3.Error, OSError, ValueError) as error:\n        print(f\'ERROR: {error}\', file=sys.stderr)\n        return 1\n\n\nif __name__ == \'__main__\':\n    sys.exit(main())\n'
STRINGS_SOURCE = '"""Export FH2 LSB2 string tables to editable mod strings.json.\n\nexport: export INPUT.str|EN.zip OUTPUT.json [--table Data_Car] [--language EN]\ndiff: diff VANILLA.str|ZIP CUSTOM.str|ZIP OUTPUT.json [--table Data_Car] [--language EN]\nlanguages: languages STRINGTABLE_DIRECTORY OUTPUT.json --table Data_Car\nZIP inputs include all STR tables by default; --table selects just one.\nUses only Python\'s standard library; input files are never modified.\n"""\nimport argparse\nimport json\nfrom pathlib import Path\nimport struct\nimport sys\nimport zipfile\n\nLANGUAGES=(\'EN\',\'GB\',\'BR\',\'CHT\',\'CZ\',\'DE\',\'ES\',\'FR\',\'HU\',\'IT\',\'JP\',\'KO\',\'MX\',\'NL\',\'PL\',\'RU\',\'DEV\',\'LOC\')\n\n\ndef read_table(data, skip_reserved=False, *, recover_stale_size=False, diagnostics=None):\n    if len(data)<36 or data[:4]!=b\'LSB2\':raise ValueError(\'Expected an LSB2 string table\')\n    flags,version,reserved,start=struct.unpack_from(\'<IHHI\',data,4)\n    if flags&1 or version>>8!=2 or start<24 or start+8>len(data):raise ValueError(\'Unsupported LSB2 header\')\n    size,count=struct.unpack_from(\'<II\',data,start)\n    end=start+size\n    pool=start+8+(count+1)*6\n    if count>65535 or size<8+(count+1)*6 or end>len(data) or (end-pool)%2:raise ValueError(\'Invalid string section\')\n\n    def parse(bound):\n        result={};used_end=pool\n        for index in range(count):\n            key,offset=struct.unpack_from(\'<HI\',data,start+8+index*6)\n            if key==65535 and skip_reserved:continue\n            if key==65535 or str(key) in result:raise ValueError(\'Duplicate or reserved string ID\')\n            at=pool+offset*2;stop=at\n            if at<pool or at>=bound:raise ValueError(\'String offset outside text section\')\n            while stop+2<=bound and data[stop:stop+2]!=b\'\\0\\0\':stop+=2\n            if stop+2>bound:raise ValueError(\'Unterminated string\')\n            result[str(key)]=data[at:stop].decode(\'utf-16le\',errors=\'strict\')\n            used_end=max(used_end,stop+2)\n        return dict(sorted(result.items(),key=lambda pair:int(pair[0]))),used_end\n\n    try:\n        return parse(end)[0]\n    except ValueError as error:\n        if not recover_stale_size or str(error) not in (\'Unterminated string\',\'String offset outside text section\'):\n            raise\n        # Some editors add the text bytes to the section size but forget the\n        # six-byte index records. Recover only this identifiable layout, with\n        # a complete UTF-16 pool ending at a plausible next indexed section.\n        try:\n            result,recovered_end=parse(len(data))\n        except ValueError:\n            raise error\n        missing=recovered_end-end\n        if missing<=0 or missing%6 or recovered_end+8>len(data):raise error\n        sections=struct.unpack_from(\'<I\',data,16)[0]\n        if not 1<sections<=64 or 20+sections*4>start or struct.unpack_from(\'<I\',data,20)[0]!=start:\n            raise error\n        next_size,next_count=struct.unpack_from(\'<II\',data,recovered_end)\n        if next_count!=count-missing//6 or next_count>65535 or next_size<8+next_count*6 or recovered_end+next_size>len(data):\n            raise error\n        if diagnostics is not None:\n            diagnostics.append(f\'stale text-section size: recovered {missing//6} added index records \'\n                               f\'({missing} missing bytes in the declared size); source file unchanged.\')\n        return result\n\n\ndef document(languages):\n    return {\'format_version\':1,\'fallback_language\':\'EN\',\'languages\':languages}\n\n\ndef read_tables(path, selected=None):\n    """Read directly from an archive; no extraction or input changes."""\n    if selected and selected.lower().endswith(\'.str\'):selected=selected[:-4]\n    if selected==\'*\':selected=None\n    def parse(data,name):\n        try:\n            notes=[]\n            result=read_table(data,skip_reserved=True,recover_stale_size=True,diagnostics=notes)\n            for note in notes:\n                print(f\'NOTE: {path.name}/{name}: {note}\',file=sys.stderr)\n            start=struct.unpack_from(\'<I\',data,12)[0]\n            count=struct.unpack_from(\'<I\',data,start+4)[0]\n            if len(result)<count:\n                print(f\'NOTE: {path.name}/{name}: reserved string ID 65535 omitted (not supported by strings.json).\',file=sys.stderr)\n            return result\n        except ValueError as error:\n            raise ValueError(f\'{path.name}/{name}: {error}\') from error\n    if not zipfile.is_zipfile(path):\n        name=selected or \'Data_Car\'\n        return {name:parse(path.read_bytes(),name)}\n    entries={}\n    with zipfile.ZipFile(path) as archive:\n        for entry in archive.infolist():\n            name=entry.filename.replace(\'\\\\\',\'/\').rsplit(\'/\',1)[-1]\n            if entry.is_dir() or not name.lower().endswith(\'.str\'):continue\n            name=name[:-4]\n            if selected and name.lower()!=selected.lower():continue\n            key=name.lower()\n            if key in entries:raise ValueError(f\'{path.name}: ambiguous duplicate table: {name}\')\n            if entry.file_size>32*1024*1024:raise ValueError(f\'{path.name}: table exceeds 32 MB: {name}\')\n            entries[key]=(name,parse(archive.read(entry),name))\n    if not entries:raise ValueError(f\'{path.name}: no matching STR tables found\'+(f\' for {selected}\' if selected else \'\'))\n    return dict(value for key,value in sorted(entries.items()))\n\n\ndef main():\n    parser=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter)\n    commands=parser.add_subparsers(dest=\'command\',required=True)\n    for verb in (\'export\',\'diff\',\'languages\'):\n        sub=commands.add_parser(verb)\n        if verb==\'diff\':sub.add_argument(\'vanilla\',type=Path)\n        sub.add_argument(\'input\',type=Path);sub.add_argument(\'output\',type=Path)\n        sub.add_argument(\'--table\',help=\'Table name; ZIP default is all tables, STR/directory default is Data_Car\')\n        if verb!=\'languages\':sub.add_argument(\'--language\',choices=LANGUAGES)\n    args=parser.parse_args()\n    protected=[args.input.resolve()]\n    if args.command==\'diff\':protected.append(args.vanilla.resolve())\n    if args.output.resolve() in protected:parser.error(\'Output must differ from the input files\')\n    if args.command==\'languages\':\n        languages={}\n        for archive in sorted(args.input.glob(\'*.zip\')):\n            code=archive.stem.upper()\n            if code not in LANGUAGES:continue\n            selected=args.table or \'Data_Car\'\n            # Directory exports preserve the existing behavior of skipping\n            # languages without the selected table.\n            with zipfile.ZipFile(archive) as z:\n                if selected!=\'*\' and not any(name.replace(\'\\\\\',\'/\').rsplit(\'/\',1)[-1].lower()==selected.lower()+\'.str\' for name in z.namelist()):continue\n            languages[code]=read_tables(archive,selected)\n        if not languages:parser.error(\'No matching tables found\')\n    else:\n        current=read_tables(args.input,args.table)\n        if args.command==\'diff\':\n            if not args.table and zipfile.is_zipfile(args.input)!=zipfile.is_zipfile(args.vanilla):\n                parser.error(\'Specify --table NAME when comparing a ZIP with a single STR file\')\n            vanilla={name.lower():values for name,values in read_tables(args.vanilla,args.table).items()}\n            changes={}\n            for name,values in current.items():\n                original=vanilla.get(name.lower(),{})\n                changed={key:text for key,text in values.items() if original.get(key)!=text}\n                if changed:changes[name]=changed\n            current=changes\n        code=args.language\n        if not code:\n            candidates=[args.input]+([args.vanilla] if args.command==\'diff\' else [])\n            code=next((p.stem.upper() for p in candidates if p.stem.upper() in LANGUAGES),\'EN\')\n        languages={code:current}\n    args.output.parent.mkdir(parents=True,exist_ok=True)\n    args.output.write_text(json.dumps(document(languages),ensure_ascii=False,indent=2)+\'\\n\',encoding=\'utf-8\')\n    print(json.dumps({\'output\':str(args.output.resolve()),\'languages\':len(languages),\n                      \'entries\':sum(len(table) for tables in languages.values() for table in tables.values())}))\n\nif __name__==\'__main__\':main()\n\n'

def namespace(source, name):
    scope = {'__name__': name, '__file__': __file__}
    exec(compile(source, __file__ + ':' + name, 'exec'), scope)
    return scope

def choose(prompt, options, default):
    print('\n' + prompt)
    for index, (label, value) in enumerate(options, 1):
        print(f'  {index}. {label}' + (' [default]' if value == default else ''))
    while True:
        answer = input('Choice (Enter for default): ').strip()
        if not answer:
            return default
        if answer.isdigit() and 1 <= int(answer) <= len(options):
            return options[int(answer)-1][1]
        print('Enter one of the listed numbers.')

def kind(path):
    with path.open('rb') as stream:
        header = stream.read(16)
    if header == b'SQLite format 3\0':
        return 'database'
    if header[:4] == b'LSB2':
        return 'strings'
    if header[:2] == b'\x05\x00':
        return 'carbin'
    if zipfile.is_zipfile(path):
        with zipfile.ZipFile(path) as archive:
            strings=any(n.lower().endswith('.str') for n in archive.namelist())
            carbins=len([n for n in archive.namelist() if n.lower().endswith('.carbin')])
            if strings and carbins:raise ValueError('ZIP contains both STR tables and carbins; use separate input archives.')
            if strings:return 'strings'
            if carbins == 1:
                return 'carbin'
    raise ValueError(f'Unsupported input: {path.name}. Use FH2 STR tables/string-table ZIPs, carbins/car ZIPs or SQLite databases.')


def run_strings(arguments):
    tool = namespace(STRINGS_SOURCE, 'strings_tool')
    old = sys.argv
    try:
        sys.argv = [__file__, *map(str, arguments)]
        tool['main']()
    finally:
        sys.argv = old
    return 0


def drag_strings(edited, base=None):
    archives=[zipfile.is_zipfile(p) for p in (base,edited) if p]
    default_table='*' if all(archives) else next(p.stem for p in (base,edited) if p and not zipfile.is_zipfile(p))
    hint='all tables; type a name to select one' if default_table=='*' else default_table
    table = input(f'String table name (Enter = {hint}): ').strip() or default_table
    if any(char in table for char in '/\\\0') or not table:
        raise ValueError('Use the game table name without a directory or .str extension.')
    if table.lower().endswith('.str'):
        table = table[:-4]
    languages = namespace(STRINGS_SOURCE, 'strings_tool')['LANGUAGES']
    default_language=next((p.stem.upper() for p in (edited,base) if p and p.stem.upper() in languages),'EN')
    while True:
        language = input(f'Language code (Enter = {default_language}; ' + ', '.join(languages) + '): ').strip().upper() or default_language
        if language in languages:
            break
        print('Enter one of the listed language codes.')
    if base is None:
        print('Full export: loading this file as a mod overrides every exported string. Use two STRs or ZIPs for a diff.')
    default = edited.parent / 'strings.json'
    text = input(f'Output JSON (Enter = {default}): ').strip().strip('"')
    output = Path(text).resolve() if text else default
    if output.resolve() in [path.resolve() for path in (base, edited) if path]:
        raise ValueError('Output must differ from the input files.')
    if output.exists() and not choose('Output exists. Replace?', [('Cancel', False), ('Replace', True)], False):
        return 1
    args = ['diff', base, edited, output] if base else ['export', edited, output]
    return run_strings([*args, '--table', table, '--language', language])

def drag_diff(arguments):
    if len(arguments) == 1 and kind(Path(arguments[0])) == 'strings':
        return drag_strings(Path(arguments[0]).resolve())
    if len(arguments) != 2:
        raise ValueError('Drop one STR/string-table ZIP to export, or two matching files to diff: vanilla first, edited second.')
    base, edited = [Path(value).resolve() for value in arguments]
    if base == edited:
        raise ValueError('Choose two different input files.')
    file_kind = kind(base)
    if kind(edited) != file_kind:
        raise ValueError('Both inputs must be the same supported file type.')
    print(f'Vanilla: {base}\nEdited:  {edited}')
    order = choose('Confirm the input order:', [('Use this order', 'keep'), ('Swap vanilla and edited', 'swap')], 'keep')
    if order == 'swap':
        base, edited = edited, base
    if file_kind == 'strings':
        return drag_strings(edited, base)
    if file_kind == 'carbin':
        print('Carbin ID policy: inherited from database.json in the same mod folder.')
        print('Set policy.id_conflicts there: error rejects duplicates; nearest remaps earlier')
        print('database/carbin references; last_wins shares IDs with the highest-priority row.')
        print('Carbin patches have no independent ID policy. Base hash mismatches warn and apply;')
        print('invalid operations and incorrect car identities are rejected.')
        if not choose('Continue with these carbin rules?', [('Continue', True), ('Cancel', False)], True):
            return 1
        tool = namespace(CARBIN_SOURCE, 'carbin_tool')
        base_data, edit_data = tool['read_car'](base), tool['read_car'](edited)
        default = edited.parent / (base.stem + '.carbin.json')
        text = input(f'Output JSON (Enter = {default}): ').strip().strip('"')
        output = Path(text).resolve() if text else default
        if output.resolve() in (base, edited):
            raise ValueError('Output must differ from the input files.')
        if output.exists():
            if choose(f'Output exists: {output}', [('Cancel', False), ('Replace it', True)], False) is False:
                return 1
        # Use the original CLI's own merge verification, warnings and writer.
        old = sys.argv
        try:
            sys.argv = [__file__, 'diff', str(base), str(edited), str(output)]
            tool['main']()
        finally:
            sys.argv = old
        return 0
    tool = namespace(DATABASE_SOURCE, 'database_tool')
    tables = input('Export only these tables (comma-separated; Enter = all): ').strip()
    selected = [name.strip() for name in tables.split(',') if name.strip()] or None
    text = input('Custom table keys (TABLE=COL1,COL2; separate tables with semicolons; Enter = automatic): ').strip()
    keys = {}
    for value in text.split(';') if text else []:
        table, separator, columns = value.strip().partition('=')
        names = [name.strip() for name in columns.split(',')]
        if not separator or not table or not all(names) or table in keys:
            raise ValueError(f'Invalid/duplicate custom key: {value}')
        keys[table] = names
    # Inspect actual changes before asking about them. Ignoring removals in this
    # read-only preview permits inspection of tables without stable keys too.
    try:
        with closing(tool['open_readonly'](base)) as original, closing(tool['open_readonly'](edited)) as custom:
            _, preview = tool['compare'](original, custom, keys=keys, tables=selected,
                                         updates='override', deletes='ignore')
            missing_keys = [table for table, counts in preview['ignored_changes'].items()
                            if counts['delete'] and not tool['choose_key'](
                                original, table, tool['columns_for'](original, table), keys)]
    except (tool['ExportError'], tool['sqlite3'].Error) as error:
        raise ValueError(str(error)) from error
    changed = {table: counts['update'] for table, counts in preview['tables'].items() if counts['update']}
    removed = {table: counts['delete'] for table, counts in preview['ignored_changes'].items() if counts['delete']}
    print(f'\nComparison: {preview["totals"]["insert"]} added, '
          f'{sum(changed.values())} changed, {sum(removed.values())} removed row(s).')
    if preview.get('filtered_view_snapshots'):
        print("Filtered views are export-time snapshots; other mods' later rows are unaffected.")
    updates = deletes = 'error'
    if changed:
        print('Changed rows: ' + ', '.join(f'{table}: {count}' for table, count in changed.items()))
        updates = choose('How should these changed rows be exported?',
                         [('Export as overrides', 'override'), ('Ignore changed rows', 'ignore'),
                          ('Cancel export', 'cancel')], 'override')
        if updates == 'cancel':
            return 1
    if removed:
        print('Removed rows: ' + ', '.join(f'{table}: {count}' for table, count in removed.items()))
        print('Including removals deletes only these exported rows when the mod loads.')
        deletes = choose('How should these removed rows be exported?',
                         [('Include explicit deletions', 'include'), ('Ignore removed rows', 'ignore'),
                          ('Cancel export', 'cancel')], 'include')
        if deletes == 'cancel':
            return 1
        if deletes == 'include':
            for table in missing_keys:
                columns = input(f'{table} has no stable key. Enter unique key columns '
                                '(comma-separated; Enter cancels): ').strip()
                if not columns:
                    print('Export cancelled: explicit deletions require a stable row key.')
                    return 1
                keys[table] = [name.strip() for name in columns.split(',')]
            if missing_keys:
                # A stable key can reclassify a removed+added pair as an update.
                # Do not leave --updates=error simply because the first preview
                # could not recognize that identity yet.
                try:
                    with closing(tool['open_readonly'](base)) as original, closing(tool['open_readonly'](edited)) as custom:
                        _, revised = tool['compare'](original, custom, keys=keys, tables=selected,
                                                     updates='override', deletes='ignore')
                except (tool['ExportError'], tool['sqlite3'].Error) as error:
                    raise ValueError(str(error)) from error
                if updates == 'error' and revised['totals']['update']:
                    print(f"With the selected keys, {revised['totals']['update']} row(s) are changed existing rows.")
                    updates = choose('How should these changed rows be exported?',
                                     [('Export as overrides', 'override'), ('Ignore changed rows', 'ignore'),
                                      ('Cancel export', 'cancel')], 'override')
                    if updates == 'cancel':
                        return 1
    conflicts = choose('policy.update_conflicts - override value conflicts at runtime:', [('Reject conflicting values', 'error'), ('Later mod wins', 'last-wins')], 'error')
    print('These runtime choices are saved together in the JSON policy object.')
    print('policy.id_conflicts also controls matching carbin JSON ID references in this mod.')
    print('last_wins shares identities across mods; only nearest remaps references. Carbin assets still follow load order.')
    ids = choose('policy.id_conflicts - conflicting inserted IDs at runtime:', [('Reject duplicate IDs', 'error'), ('Assign nearest available ID; later mod keeps requested ID', 'nearest'), ('Share IDs; highest-priority mod supplies each duplicate row', 'last_wins')], 'error')
    # Inspect the actual selected export, including the chosen delete/update
    # behavior, rather than warning about unrelated unexported tables.
    try:
        with closing(tool['open_readonly'](base)) as original, closing(tool['open_readonly'](edited)) as custom:
            proposed, _ = tool['compare'](original, custom, keys=keys, tables=selected, updates=updates, deletes=deletes)
            violations = tool['scratch_foreign_keys'](original, proposed)
    except (tool['ExportError'], tool['sqlite3'].Error) as error:
        raise ValueError(str(error)) from error
    foreign_keys = 'error'
    if violations:
        print(f"The selected export contains {len(violations)} new declared foreign-key violation(s).")
        for violation in violations[:8]:
            print(f"  {violation['table']} key={violation['key']} -> {violation['parent_table']}: {violation['references']}")
        print('Allow preserves the database values as-is; it does not create the missing parent records.')
        print('Loading policy.foreign_keys=allow requires Extra Options 0.2.210 or newer.')
        foreign_keys = choose('policy.foreign_keys - missing referenced records:',
                              [('Reject export', 'error'), ('Preserve references as-is', 'allow')], 'error')
    target = input('Target database path (Enter = media/stripped/gamedbRC.slt): ').strip() or 'media/stripped/gamedbRC.slt'
    output_text = input(f'Output JSON (Enter = {edited.parent / "database.json"}): ').strip().strip('"')
    output = Path(output_text).resolve() if output_text else edited.parent / 'database.json'
    report = choose('Also write a validation report?', [('Yes', True), ('No', False)], True)
    report_path = output.with_name(output.stem + '.report.json')
    if report:
        text = input(f'Validation report path (Enter = {report_path}): ').strip().strip('"')
        if text:
            report_path = Path(text).resolve()
    args = [str(base), str(edited), '-o', str(output), '--updates', updates, '--deletes', deletes,
            '--conflicts', conflicts, '--id-conflicts', ids, '--foreign-keys', foreign_keys, '--target', target]
    for table in selected or []:
        args += ['--table', table]
    for table, columns in keys.items():
        args += ['--key', table + '=' + ','.join(columns)]
    if report:
        args += ['--report', str(report_path)]
    print(f'\nExport choices: --updates {updates} --deletes {deletes}')
    print(f'Runtime policy: id_conflicts={ids}, update_conflicts={conflicts}, foreign_keys={foreign_keys}')
    outputs = [output] + ([report_path] if report else [])
    if any(path.exists() for path in outputs):
        if not choose('Output/report already exists. Replace?', [('Cancel', False), ('Replace', True)], False):
            return 1
        args += ['--force']
    return tool['main'](args)


def main():
    args = sys.argv[1:]
    if not args or args[0] in ('--help','-h'):
        print(__doc__)
        return 0
    if args[0] == 'database':
        return namespace(DATABASE_SOURCE, 'database_tool')['main'](args[1:])
    if args[0] == 'strings':
        try:
            return run_strings(args[1:])
        except (ValueError, OSError, zipfile.BadZipFile) as error:
            print(f'ERROR: {error}', file=sys.stderr)
            return 1
    if args[0] == 'carbin':
        print('Carbin ID policy: inherited from database.json in the same mod folder.')
        print('Set policy.id_conflicts there: error rejects duplicates; nearest remaps earlier')
        print('database/carbin references; last_wins shares IDs with the highest-priority row.')
        print('Carbin patches have no independent ID policy. Base hash mismatches warn and apply;')
        print('invalid operations and incorrect car identities are rejected.')
        if not choose('Continue with these carbin rules?', [('Continue', True), ('Cancel', False)], True):
            return 1
        tool = namespace(CARBIN_SOURCE, 'carbin_tool')
        sys.argv = [__file__, *args[1:]]
        tool['main']()
        return 0
    try:
        return drag_diff(args)
    except (ValueError, OSError, EOFError, zipfile.BadZipFile) as error:
        print(f'ERROR: {error}', file=sys.stderr)
        return 1

if __name__ == '__main__':
    sys.exit(main())
